parameters.functionScript:
/*
 * WHICH LANGUAGE ARE WE ACTUALLY SERVING? (TASK-L162 §1)
 *
 * `want` is what the one owner — the `i18next` node in App — says the viewer
 * reads. This resolves it against the locales this template actually HAS
 * CONTENT FOR, and answers "en" for everything else.
 *
 * That matters for a reason only driving finds. The i18next module's own
 * language detector runs before anything here (querystring `lng`, cookie,
 * localStorage, sessionStorage, navigator, htmlTag — baked into the vendored
 * bundle, with no port to configure it), so `CurrentLanguage` can be "fr" on a
 * French laptop one tick after load. Passing that straight through would
 * register the ENGLISH strings as the French bundle and hand every reader a
 * language we have only the NAME of.
 *
 * It is also the ordering guarantee. This node is strictly UPSTREAM of the
 * merge, so `Language Bundle.Language` is always set before the `Bundle` JSON
 * that the merge produces arrives — and `Language Bundle` reads its Language
 * at the moment Bundle changes, never on its own.
 */
function plain(x) {
  if (x === null || x === undefined) return x;
  if (Array.isArray(x)) return x.map(plain);
  if (typeof x === 'object') {
    if (typeof x.get === 'function' && x.data && typeof x.data === 'object') return plain(x.data);
    if (Array.isArray(x.items)) return plain(x.items);
    const out = {};
    for (const k of Object.keys(x)) out[k] = plain(x[k]);
    return out;
  }
  return x;
}

const rows = plain(Inputs.locales) || [];
const overlay = rows[0] || {};

/* English is the BASE layer, never an overlay key — so it is never listed here. */
const available = Object.keys(overlay).filter((k) => k.charAt(0) !== '_');

const want = String(Inputs.want || '').trim();
let resolved = 'en';
if (want) {
  if (available.indexOf(want) !== -1) resolved = want;
  else {
    const base = want.split('-')[0];
    if (available.indexOf(base) !== -1) resolved = base;
  }
}

Outputs.resolved = resolved;
Outputs.available = ['en'].concat(available).join(', ');
